1	package com.example.starter.firmware.service;
2	
3	import com.example.starter.firmware.error.ApiException;
4	import com.example.starter.firmware.repo.IdempotencyRepository;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import org.springframework.dao.DuplicateKeyException;
7	import org.springframework.stereotype.Service;
8	import org.springframework.transaction.support.TransactionTemplate;
9	
10	import java.util.function.Supplier;
11	
12	/**
13	 * 写操作幂等执行器：同一事务内完成业务变更与去重记录写入，原子提交。
14	 * 同键同参重放原成功结果；同键异参返回 409；业务失败回滚，不占键。
15	 * 同 requestId 的执行通过分段锁串行化，避免并发下检查与写入之间的竞态；
16	 * 数据库唯一约束作为最终兜底。
17	 */
18	@Service
19	public class IdempotencyService {
20	
21	    /**
22	     * 内部信号：并发下同键插入冲突，回滚当前事务后改为重放已提交记录。
23	     */
24	    private static final class ReplayNeededException extends RuntimeException {
25	    }
26	
27	    private static final int LOCK_STRIPES = 256;
28	
