17	
18	/**
19	 * 固件灰度投放 API 主流程、失败分支与幂等边界测试（H2 内存库，MODE=MySQL）。
20	 */
21	@SpringBootTest
22	@AutoConfigureMockMvc
23	class FirmwareApiTest {
24	
25	    @Autowired
26	    private MockMvc mockMvc;
27	
28	    @Autowired
29	    private JdbcTemplate jdbc;
30	
31	    private static long idOf(MvcResult result, String path) throws Exception {
32	        Number value = com.jayway.jsonpath.JsonPath.read(result.getResponse().getContentAsString(), path);
33	        return value.longValue();
34	    }
35	
36	    @BeforeEach
37	    void cleanUp() {
38	        jdbc.update("DELETE FROM rollout_task");
39	        jdbc.update("DELETE FROM release_order");
40	        jdbc.update("DELETE FROM device");
41	        jdbc.update("DELETE FROM idempotency_record");
42	    }
43	
44	    private String registerDevice(String requestId, String deviceId, String model, String version, int bucket)
45	            throws Exception {
46	        MvcResult result = mockMvc.perform(post("/api/devices")
47	                        .contentType("application/json")
48	                        .content("""
49	                                {"requestId":"%s","deviceId":"%s","model":"%s","currentVersion":"%s","bucketNo":%d}
50	                                """.formatted(requestId, deviceId, model, version, bucket)))
51	                .andReturn();
52	        return result.getResponse().getContentAsString();
53	    }
54	
55	    private String createRelease(String requestId, String model, String from, String to, int ratio)
56	            throws Exception {
57	        MvcResult result = mockMvc.perform(post("/api/releases")
58	                        .contentType("application/json")
59	                        .content("""
60	                                {"requestId":"%s","model":"%s","fromVersion":"%s","toVersion":"%s","ratio":%d}
61	                                """.formatted(requestId, model, from, to, ratio)))
62	                .andReturn();
63	        return result.getResponse().getContentAsString();
64	    }
65	
66	    private long releaseIdOf(String responseBody) {
67	        Number id = com.jayway.jsonpath.JsonPath.read(responseBody, "$.releaseId");
68	        return id.longValue();
69	    }
70	
71	    @Test
72	    void 主流程_登记发布拉取回执成功并更新设备版本() throws Exception {
73	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
74	                        {"requestId":"r1","deviceId":"d1","model":"m1","currentVersion":"1.0.0","bucketNo":5}
75	                        """))
76	                .andExpect(status().isOk())
77	                .andExpect(jsonPath("$.deviceId").value("d1"))
78	                .andExpect(jsonPath("$.bucketNo").value(5));
79	
80	        MvcResult release = mockMvc.perform(post("/api/releases").contentType("application/json").content("""
81	                        {"requestId":"r2","model":"m1","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":10}
82	                        """))
83	                .andExpect(status().isOk())
84	                .andExpect(jsonPath("$.version").value(1))
85	                .andExpect(jsonPath("$.status").value("ACTIVE"))
86	                .andReturn();
87	        long releaseId = idOf(release, "$.releaseId");
88	
89	        MvcResult pull = mockMvc.perform(post("/api/devices/d1/pull").contentType("application/json")
90	                        .content("{\"requestId\":\"r3\"}"))
91	                .andExpect(status().isOk())
92	                .andExpect(jsonPath("$.task.status").value("PENDING"))
93	                .andExpect(jsonPath("$.task.fromVersion").value("1.0.0"))
94	                .andExpect(jsonPath("$.task.toVersion").value("2.0.0"))
95	                .andReturn();
96	        long taskId = idOf(pull, "$.task.taskId");
97	
98	        mockMvc.perform(post("/api/tasks/" + taskId + "/receipt").contentType("application/json")
99	                        .content("{\"requestId\":\"r4\",\"result\":\"SUCCESS\"}"))
100	                .andExpect(status().isOk())
101	                .andExpect(jsonPath("$.status").value("SUCCESS"));
102	
103	        mockMvc.perform(get("/api/devices/d1"))
104	                .andExpect(status().isOk())
105	                .andExpect(jsonPath("$.currentVersion").value("2.0.0"));
106	
107	        mockMvc.perform(get("/api/releases/" + releaseId + "/tasks"))
108	                .andExpect(status().isOk())
109	                .andExpect(jsonPath("$.tasks.length()").value(1))
110	                .andExpect(jsonPath("$.tasks[0].status").value("SUCCESS"));
111	    }
112	
113	    @Test
114	    void 设备登记_重复设备冲突_参数校验() throws Exception {
115	        registerDevice("r1", "d1", "m1", "1.0.0", 5);
116	
117	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
118	                        {"requestId":"r2","deviceId":"d1","model":"m1","currentVersion":"1.0.0","bucketNo":5}
119	                        """))
120	                .andExpect(status().isConflict())
121	                .andExpect(jsonPath("$.code").value("DEVICE_EXISTS"));
122	
123	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
124	                        {"requestId":"r3","deviceId":"d2","model":"m1","currentVersion":"1.0.0","bucketNo":100}
125	                        """))
126	                .andExpect(status().isBadRequest());
