128	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
129	                        {"deviceId":"d3","model":"m1","currentVersion":"1.0.0","bucketNo":1}
130	                        """))
131	                .andExpect(status().isBadRequest());
132	    }
133	
134	    @Test
135	    void 幂等_同键同参重放原结果_异参409_失败不占键() throws Exception {
136	        String first = registerDevice("rid-1", "d1", "m1", "1.0.0", 5);
137	        assertThat(first).contains("\"deviceId\":\"d1\"");
138	
139	        String replay = registerDevice("rid-1", "d1", "m1", "1.0.0", 5);
140	        assertThat(replay).isEqualTo(first);
141	        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM device", Long.class)).isEqualTo(1);
142	
143	        mockMvc.perform(post("/api/devices").contentType("application/json").content("""
144	                        {"requestId":"rid-1","deviceId":"d9","model":"m1","currentVersion":"1.0.0","bucketNo":5}
145	                        """))
146	                .andExpect(status().isConflict())
147	                .andExpect(jsonPath("$.code").value("REQUEST_ID_CONFLICT"));
