149	        // 失败不占键：先以错误参数触发 409，再用同 requestId 正确参数成功
150	        createRelease("rid-x", "m1", "1.0.0", "1.0.0", 10); // 400 在 Service 外，requestId 未入库
151	        MvcResult created = mockMvc.perform(post("/api/releases").contentType("application/json").content("""
152	                        {"requestId":"rid-y","model":"m1","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":10}
