package com.example.starter.firmware.domain;

/**
 * 发布单状态：ACTIVE 投放中；CANCELLED 已取消；COMPLETED 已完成（金丝雀最高级别推进后的终态，不再解锁更多设备）。
 */
public enum ReleaseStatus {
    ACTIVE,
    CANCELLED,
    COMPLETED
}

package com.example.starter.firmware.domain;

/**
 * 固件灰度发布单。
 *
 * @param id            发布单ID
 * @param version       发布单版本号，从1开始，每次扩量成功加一
 * @param model         目标设备型号
 * @param fromVersion   来源固件版本
 * @param toVersion     目标固件版本，必须与来源版本不同
 * @param ratio         当前生效投放比例，取值0~100，只增不减；金丝雀发布单等于当前已解锁最高级别的比例
 * @param status        状态：ACTIVE 投放中，CANCELLED 已取消，COMPLETED 已完成
 * @param levelCount    金丝雀验证级别总数，0 表示非金丝雀发布单
 * @param unlockedLevel 当前已解锁的最高金丝雀级别，0 表示非金丝雀发布单
 */
public record ReleaseOrder(long id, int version, String model, String fromVersion, String toVersion,
                           int ratio, ReleaseStatus status, int levelCount, int unlockedLevel) {

    /**
     * 是否声明了金丝雀分级验证。
     */
    public boolean isCanary() {
        return levelCount > 0;
    }
}

package com.example.starter.firmware.domain;

/**
 * 金丝雀验证级别及样本统计。样本与失败数随设备回执首次进入终态累计，推进不重置。
 *
 * @param releaseId      所属发布单ID
 * @param levelNo        级别序号，从1开始
 * @param ratio          该级别投放比例，取值1~100，各级别严格递增
 * @param minSamples     最小验证样本数，取值1~50
 * @param maxFailureRate 失败率上限，单位百分之一（百分数），取值1~100
 * @param sampleCount    已进入终态（SUCCESS/FAILED）的样本数
 * @param failCount      样本中结果为 FAILED 的数量
 * @param unlocked       是否已解锁，创建时仅第1级解锁
 */
public record CanaryLevel(long releaseId, int levelNo, int ratio, int minSamples, int maxFailureRate,
                          int sampleCount, int failCount, boolean unlocked) {

    /**
     * 失败率是否超过上限（整数交叉相乘，避免浮点误差）。样本为0时不超限。
     */
    public boolean failureRateExceeded() {
        return sampleCount > 0 && failCount * 100 > maxFailureRate * sampleCount;
    }
}

package com.example.starter.firmware.domain;

import java.time.LocalDateTime;

/**
 * 金丝雀推进历史记录，只增不改。
 *
 * @param releaseId   所属发布单ID
 * @param fromLevel   推进前已解锁的最高级别
 * @param toLevel     推进目标级别；等于级别总数+1 表示发布单进入 COMPLETED 终态
 * @param promoteKey  推进幂等键，全局唯一
 * @param sampleCount 推进成功时当前级别样本数快照
 * @param failCount   推进成功时当前级别失败样本数快照
 * @param promotedAt  推进时间（服务器本地时区）
 */
public record CanaryPromotion(long releaseId, int fromLevel, int toLevel, String promoteKey,
                              int sampleCount, int failCount, LocalDateTime promotedAt) {
}

