package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.ReleaseStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.sql.PreparedStatement;
import java.util.Optional;

/**
 * 发布单数据访问。扩量、取消、推进、拉取、回执共用行锁（SELECT ... FOR UPDATE）形成一致提交顺序。
 */
@Repository
public class ReleaseRepository {

    private static final RowMapper<ReleaseOrder> MAPPER = (rs, rowNum) -> new ReleaseOrder(
            rs.getLong("id"), rs.getInt("version"), rs.getString("model"),
            rs.getString("from_version"), rs.getString("to_version"),
            rs.getInt("ratio"), ReleaseStatus.valueOf(rs.getString("status")),
            rs.getInt("level_count"), rs.getInt("unlocked_level"));

    private static final String COLUMNS =
            "id, version, model, from_version, to_version, ratio, status, level_count, unlocked_level";

    private final JdbcTemplate jdbc;

    public ReleaseRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 创建发布单。levelCount 大于0时为金丝雀发布单，初始仅解锁第1级，ratio 取第1级比例。
     */
    public long insert(String model, String fromVersion, String toVersion, int ratio, int levelCount) {
        int unlockedLevel = levelCount > 0 ? 1 : 0;
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO release_order (version, model, from_version, to_version, ratio, status,"
                            + " active_model, level_count, unlocked_level)"
                            + " VALUES (1, ?, ?, ?, ?, 'ACTIVE', ?, ?, ?)",
                    new String[]{"id"});
            ps.setString(1, model);
            ps.setString(2, fromVersion);
            ps.setString(3, toVersion);
            ps.setInt(4, ratio);
            ps.setString(5, model);
            ps.setInt(6, levelCount);
            ps.setInt(7, unlockedLevel);
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    public Optional<ReleaseOrder> findById(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE id = ?", MAPPER, id)
                .stream().findFirst();
    }

    public Optional<ReleaseOrder> findByIdForUpdate(long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE id = ? FOR UPDATE", MAPPER, id)
                .stream().findFirst();
    }

    public Optional<ReleaseOrder> findActiveByModel(String model) {
        return jdbc.query("SELECT " + COLUMNS + " FROM release_order WHERE active_model = ?", MAPPER, model)
                .stream().findFirst();
    }

    /**
     * 乐观扩量：仅当版本与状态匹配时生效，返回影响行数。
     */
    public int expand(long id, int expectedVersion, int newRatio) {
        return jdbc.update("UPDATE release_order SET version = version + 1, ratio = ?, updated_at = CURRENT_TIMESTAMP"
                + " WHERE id = ? AND version = ? AND status = 'ACTIVE'", newRatio, id, expectedVersion);
    }

    public void cancel(long id) {
        jdbc.update("UPDATE release_order SET status = 'CANCELLED', active_model = NULL,"
                + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);
    }

    /**
     * 金丝雀推进：解锁到指定级别并同步生效比例为该级别比例。
     */
    public void unlockLevel(long id, int unlockedLevel, int ratio) {
        jdbc.update("UPDATE release_order SET unlocked_level = ?, ratio = ?, updated_at = CURRENT_TIMESTAMP"
                + " WHERE id = ?", unlockedLevel, ratio, id);
    }

    /**
     * 金丝雀最高级别推进完成：进入 COMPLETED 终态并释放型号占用，不再解锁更多设备。
     */
    public void complete(long id) {
        jdbc.update("UPDATE release_order SET status = 'COMPLETED', active_model = NULL,"
                + " updated_at = CURRENT_TIMESTAMP WHERE id = ?", id);
    }
}

package com.example.starter.firmware.repo;

import com.example.starter.firmware.domain.CanaryLevel;
import com.example.starter.firmware.domain.CanaryPromotion;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 金丝雀级别与推进历史数据访问。样本统计的读改写在发布单行锁保护下与推进串行化。
 */
@Repository
public class CanaryRepository {

    private static final RowMapper<CanaryLevel> LEVEL_MAPPER = (rs, rowNum) -> new CanaryLevel(
            rs.getLong("release_id"), rs.getInt("level_no"), rs.getInt("ratio"),
            rs.getInt("min_samples"), rs.getInt("max_failure_rate"),
            rs.getInt("sample_count"), rs.getInt("fail_count"), rs.getBoolean("unlocked"));

    private static final String LEVEL_COLUMNS =
            "release_id, level_no, ratio, min_samples, max_failure_rate, sample_count, fail_count, unlocked";

    private static final RowMapper<CanaryPromotion> PROMOTION_MAPPER = (rs, rowNum) -> new CanaryPromotion(
            rs.getLong("release_id"), rs.getInt("from_level"), rs.getInt("to_level"),
            rs.getString("promote_key"), rs.getInt("sample_count"), rs.getInt("fail_count"),
            rs.getTimestamp("created_at").toLocalDateTime());

    private static final String PROMOTION_COLUMNS =
            "release_id, from_level, to_level, promote_key, sample_count, fail_count, created_at";

    private final JdbcTemplate jdbc;

    public CanaryRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 创建发布单的所有级别，初始仅第1级解锁。
     */
    public void insertLevels(long releaseId, List<LevelSpec> levels) {
        for (int i = 0; i < levels.size(); i++) {
            LevelSpec spec = levels.get(i);
            boolean unlocked = i == 0;
            jdbc.update("INSERT INTO canary_level (release_id, level_no, ratio, min_samples, max_failure_rate,"
                            + " unlocked, unlocked_at) VALUES (?, ?, ?, ?, ?, ?,"
                            + (unlocked ? " CURRENT_TIMESTAMP)" : " NULL)"),
                    releaseId, i + 1, spec.ratio(), spec.minSamples(), spec.maxFailureRate(), unlocked);
        }
    }

    public List<CanaryLevel> findLevels(long releaseId) {
        return jdbc.query("SELECT " + LEVEL_COLUMNS + " FROM canary_level WHERE release_id = ? ORDER BY level_no",
                LEVEL_MAPPER, releaseId);
    }

    public Optional<CanaryLevel> findLevel(long releaseId, int levelNo) {
        return jdbc.query("SELECT " + LEVEL_COLUMNS + " FROM canary_level WHERE release_id = ? AND level_no = ?",
                LEVEL_MAPPER, releaseId, levelNo).stream().findFirst();
    }

    /**
     * 设备回执首次进入终态时累计当前解锁级别样本；failed 为 true 时同时累计失败数。
     */
    public void incrementSample(long releaseId, int levelNo, boolean failed) {
        jdbc.update("UPDATE canary_level SET sample_count = sample_count + 1,"
                        + " fail_count = fail_count + ? WHERE release_id = ? AND level_no = ?",
